Loom.scene("b01", {
  build(ctx) {
    const { kit, m } = ctx;
    const S = Loom.style;
    const beatId = ctx.beat.id;
    const enter = S.dur("enter");
    const solid = (parent, x, y, w, h, token, r) =>
      Loom.svg("rect", { x, y, width: w, height: h, rx: r == null ? 12 : r, fill: S.c(token) }, parent);
    const tEngineer = ctx.cue("on-call engineer");
    const tTag = ctx.cue("routine change");
    const tStore = ctx.cue("made-up online store");
    const tStop = ctx.cue("stops taking orders");
    const FLAT = 0.7;                                   // the flatline's own duration; the stamp reuses it
    const pressDown = S.dur("exit") * 0.3, pressUp = S.dur("exit") * 0.7;   // the button press, from the style
    const tPress = tTag + enter * 0.85;                 // the tag has landed, the button is pressed
    const tRun = tStore + 0.5;                          // the panel is assembling; the line starts at its left
    const tFlat = tStop + FLAT;                         // the instant the line is flat
    const win = ctx.el("window", { x: 150, y: 266, w: 340, h: 200, kind: "scenery", exit: "recede" });
    solid(win.inner, 0, 0, 340, 200, "surface", 6);
    kit.rect(win.inner, 0, 0, 340, 200, { fill: "ink", r: 6 });
    kit.line(win.inner, 120, 4, 120, 196, { stroke: "surface", sw: 6 });
    Loom.svg("circle", { cx: 240, cy: 100, r: 50, fill: S.c("field") }, win.inner);
    kit.icon(win.inner, "moon", { x: 240, y: 100, size: 76, color: "ink" });
    [[52, 44], [72, 150], [178, 34], [300, 168], [296, 40]].forEach(([sx, sy]) =>
      Loom.svg("circle", { cx: sx, cy: sy, r: 4.5, fill: S.c("field") }, win.inner));
    const eng = ctx.el("engineer", { x: 150, y: 412, w: 340, h: 340, kind: "character", exit: "recede" });
    const pNeutral = kit.peep(eng.inner, "woman", "neutral", { x: 170, y: 170, size: 340, cloth: "accent2" });
    const pSurprised = kit.peep(eng.inner, "woman", "surprised", { x: 170, y: 170, size: 340, cloth: "accent2" });
    pSurprised.setAttribute("opacity", "0");
    const desk = ctx.el("desk", { x: 120, y: 722, w: 780, h: 178, kind: "scenery", exit: "recede" });
    solid(desk.inner, 0, 0, 780, 48, "surface2", 8);
    kit.rect(desk.inner, 0, 0, 780, 48, { fill: "surface2", r: 8 });
    kit.line(desk.inner, 70, 50, 70, 176, { sw: 5 });
    kit.line(desk.inner, 710, 50, 710, 176, { sw: 5 });
    const lap = ctx.el("laptop", { x: 520, y: 424, w: 380, h: 300, kind: "instrument", exit: "recede" });
    solid(lap.inner, 30, 0, 320, 262, "surface2", 16);
    kit.rect(lap.inner, 30, 0, 320, 262, { fill: "none", r: 16 });
    solid(lap.inner, 48, 18, 284, 226, "surface", 8);
    kit.rect(lap.inner, 48, 18, 284, 226, { fill: "none", r: 8, sw: 2.4 });
    kit.line(lap.inner, 70, 128, 270, 128, { stroke: "muted", sw: 3 });
    kit.line(lap.inner, 70, 148, 200, 148, { stroke: "muted", sw: 3 });
    solid(lap.inner, 0, 262, 380, 28, "surface2", 12);
    kit.rect(lap.inner, 0, 262, 380, 28, { fill: "none", r: 12 });
    const btn = ctx.el("deploy_button", { x: 670, y: 580, w: 80, h: 80, kind: "icon", exit: "recede" });
    Loom.svg("circle", { cx: 40, cy: 40, r: 38, fill: S.c("surface") }, btn.inner);
    kit.disc(btn.inner, 40, 40, 38, { fill: "accent" });
    kit.icon(btn.inner, "rocket", { x: 40, y: 40, size: 46, color: "ink" });
    const tag = ctx.el("change_tag", { x: 580, y: 452, w: 250, h: 74, kind: "card", exit: "recede" });
    solid(tag.inner, 0, 0, 250, 74, "surface", 8);
    kit.rect(tag.inner, 0, 0, 250, 74, { fill: "accent", r: 8 });
    kit.text(tag.inner, "Routine change", { role: "label", x: 0, y: 0, w: 250, h: 74, maxLines: 1, align: "center", valign: "middle" });
    const t0 = ctx.start + 0.2;
    m.assemble(desk, t0);
    m.reveal(win, t0 + 0.15);
    m.settle(lap, t0 + 0.3);
    m.pop(btn, t0 + 0.7, { overshoot: false });
    m.settle(eng, tEngineer, { dy: 24 });
    m.drop(tag, tTag);
    Loom.tween(btn.inner, { scale: 1, transformOrigin: "50% 50%" }, { scale: 0.92, transformOrigin: "50% 50%", duration: pressDown, ease: Loom.ease.exit }, tPress, { kind: "press", beat: beatId, name: btn.name, content: true });
    Loom.tween(btn.inner, { scale: 0.92, transformOrigin: "50% 50%" }, { scale: 1, transformOrigin: "50% 50%", duration: pressUp, ease: Loom.ease.overshoot }, tPress + pressDown, { kind: "press", beat: beatId, name: btn.name, content: true });
    const PX = 1040, PY = 240, PW = 760, PH = 520;
    const panel = ctx.el("store_panel", { x: PX, y: PY, w: PW, h: PH, kind: "card", exit: "displace" });
    solid(panel.inner, 0, 0, PW, PH, "surface", 20);
    kit.rect(panel.inner, 0, 0, PW, PH, { fill: "none", r: 20 });
    kit.icon(panel.inner, "store", { x: 72, y: 62, size: 60, color: "accent2" });
    kit.text(panel.inner, "Online store", { role: "lead", x: 124, y: 22, w: 420, h: 80, maxLines: 1, valign: "middle" });
    kit.line(panel.inner, 36, 116, PW - 36, 116, { sw: 2.6 });
    kit.line(panel.inner, 56, 160, 56, 450, { sw: 2.6 });             // plot axis, no values
    kit.line(panel.inner, 56, 450, PW - 50, 450, { sw: 3.6 });        // the baseline
    m.assemble(panel, tStore);
    const lab = ctx.el("orders_label", { x: PX + 76, y: PY + 176, w: 220, h: 44, kind: "text", exit: "wipe" });
    kit.text(lab.inner, "Orders", { role: "label", x: 0, y: 0, w: 220, h: 44, maxLines: 1, color: "muted" });
    m.reveal(lab, tRun - 0.1, { dy: 8 });
    const line = ctx.el("orders_line", { x: PX, y: PY, w: PW, h: PH, kind: "value", exit: "recede" });
    const LEVEL = 280, BASE = 450, X0 = 76, PERIOD = 36, TICKS = 12;
    const rng = Loom.rng("b01-orders");
    let dA = `M${X0} ${LEVEL}`;
    for (let i = 0; i < TICKS; i++) {
      const x = X0 + i * PERIOD, a = 22 + Math.round(rng() * 12);
      dA += ` L${x + 14} ${LEVEL} L${x + 20} ${LEVEL - a} L${x + 27} ${LEVEL + 6} L${x + PERIOD} ${LEVEL}`;
    }
    const xEnd = X0 + TICKS * PERIOD;
    const dB = `M${xEnd} ${LEVEL} C${xEnd + 8} ${LEVEL + 60} ${xEnd + 14} ${BASE - 50} ${xEnd + 22} ${BASE} L${PW - 60} ${BASE}`;
    const pathA = kit.path(line.inner, dA, { stroke: "pos", sw: 6 });
    const pathB = kit.path(line.inner, dB, { stroke: "neg", sw: 6 });
    const dot = Loom.svg("circle", { cx: X0, cy: LEVEL, r: 11, fill: S.c("pos"), opacity: 0 }, line.inner);
    const LA = pathA.getTotalLength(), LB = pathB.getTotalLength();
    pathA.setAttribute("stroke-dasharray", `${LA} ${LA}`); pathA.setAttribute("stroke-dashoffset", LA);
    pathB.setAttribute("stroke-dasharray", `${LB} ${LB}`); pathB.setAttribute("stroke-dashoffset", LB);
    m.reveal(line, tRun, { dy: 0, dur: S.dur("exit") * 0.4 });
    const meta = { kind: "value_travel", beat: beatId, content: true, name: line.name };
    Loom.drive((e) => {
      pathA.setAttribute("stroke-dashoffset", (LA * (1 - e)).toFixed(2));
      const pt = pathA.getPointAtLength(LA * e);
      dot.setAttribute("cx", pt.x.toFixed(2)); dot.setAttribute("cy", pt.y.toFixed(2));
      dot.setAttribute("opacity", e > 0 ? 1 : 0);
      dot.setAttribute("fill", S.c("pos"));
    }, tRun, Math.max(0.6, tStop - tRun), "linear", meta);
    Loom.drive((e) => {
      pathB.setAttribute("stroke-dashoffset", (LB * (1 - e)).toFixed(2));
      const pt = pathB.getPointAtLength(LB * e);
      dot.setAttribute("cx", pt.x.toFixed(2)); dot.setAttribute("cy", pt.y.toFixed(2));
      dot.setAttribute("fill", S.c(e > 0 ? "neg" : "pos"));
    }, tStop, FLAT, "enter", meta);
    Loom.tl.set(pNeutral, { opacity: 1 }, 0);
    Loom.tl.set(pSurprised, { opacity: 0 }, 0);
    Loom.tl.set(pNeutral, { opacity: 0 }, tFlat);
    Loom.tl.set(pSurprised, { opacity: 1 }, tFlat);
    const note = ctx.motif("incident_note", { x: 1180, y: 790, w: 480, h: 100 });
    const ng = Loom.svg("g", { transform: "rotate(-2.5 240 50)" }, note.inner);
    solid(ng, 0, 0, 480, 100, "surface", 14);
    kit.rect(ng, 0, 0, 480, 100, { fill: "none", stroke: "neg", sw: 5, r: 14 });
    kit.icon(ng, "shopping-cart", { x: 62, y: 50, size: 60, color: "neg" });
    kit.text(ng, "Orders stopped", { role: "lead", x: 112, y: 0, w: 350, h: 100, maxLines: 1, valign: "middle", weight: 800 });
    m.stamp(note, tFlat);
  },
});

Loom.scene("b02", {
  build(ctx) {
    const { kit, m } = ctx;
    const f = (v) => Math.round(v * 10) / 10;
    const ROOM = { x0: 100, y0: 90, x1: 1860, y1: 900, gapA: 300, gapB: 420 };
    const TABLE = { cx: 800, cy: 500, rx: 380, ry: 150 };
    const BOARD = { x: 1440, y: 180, w: 400, h: 600 };
    const NOTE_AT = { x: 1470, y: 220, scale: 0.6 };
    const NOTE_CENTRE = { x: NOTE_AT.x + 480 * NOTE_AT.scale / 2, y: NOTE_AT.y + 100 * NOTE_AT.scale / 2 };
    const ENG = { x: 470, y: 660 };
    const HEAD_R = 44, RING_R = 62;
    const PEERS = [
      { name: "head_top_left", x: 480, y: 330, bend: 0 },
      { name: "head_top", x: 800, y: 300, bend: 0 },
      { name: "head_top_right", x: 1120, y: 330, bend: 0 },
      { name: "head_bottom_right", x: 1120, y: 670, bend: 90 }, // its line arcs over the table, clear of the bottom head
      { name: "head_bottom", x: 800, y: 700, bend: 0 },
    ];
    const tRoom = ctx.cue("Next morning");            // the room starts to be drawn
    const tOpen = ctx.cue("the post-mortem opens");   // the heads arrive as peers
    const tTurn = ctx.cue("head in the room");        // the first head begins to turn
    const tLines = ctx.cue("turns to the engineer");  // sight lines converge as the last head locks on
    const tCap = ctx.cue("the engineer");             // caption settles
    const turnDur = ctx.style.dur("move") * 1.25;     // ~0.45 s per turn
    const turnGap = ctx.style.dur("stagger") * 3.3;   // ~0.3 s between heads
    const popGap = ctx.style.dur("stagger") * 0.66;   // tight stagger for peers arriving
    const drawDur = ctx.style.dur("draw");
    const note = ctx.adopt("incident_note");
    const tBoard = tRoom + 0.25;
    const tLand = tBoard + drawDur * 0.6 + 0.02;
    if (note) ctx.travelTo(note, NOTE_AT, ctx.start - 0.5, tLand - (ctx.start - 0.5));
    const room = ctx.el("room", { x: 0, y: 0, w: 1920, h: 1080, kind: "scenery", exit: "recede" });
    {
      const g = Loom.svg("g", {}, room.inner);
      const w = { sw: 7 };
      kit.line(g, ROOM.x0, ROOM.y0, ROOM.x1, ROOM.y0, w);
      kit.line(g, ROOM.x0, ROOM.y0, ROOM.x0, ROOM.y1, w);
      kit.line(g, ROOM.x1, ROOM.y0, ROOM.x1, ROOM.y1, w);
      kit.line(g, ROOM.x0, ROOM.y1, ROOM.gapA, ROOM.y1, w);
      kit.line(g, ROOM.gapB, ROOM.y1, ROOM.x1, ROOM.y1, w);
      kit.line(g, ROOM.gapA, ROOM.y1 - 12, ROOM.gapA, ROOM.y1 + 12, w);   // door jambs
      kit.line(g, ROOM.gapB, ROOM.y1 - 12, ROOM.gapB, ROOM.y1 + 12, w);
    }
    m.draw(room, tRoom, { dur: drawDur });
    const table = ctx.el("table", { x: 0, y: 0, w: 1920, h: 1080, kind: "scenery", exit: "recede" });
    {
      const ell = (rx, ry) => `M${TABLE.cx - rx} ${TABLE.cy} A${rx} ${ry} 0 1 0 ${TABLE.cx + rx} ${TABLE.cy} A${rx} ${ry} 0 1 0 ${TABLE.cx - rx} ${TABLE.cy} Z`;
      const top = Loom.svg("g", { opacity: 0.3 }, table.inner);           // hachure tone, kept quiet
      kit.sketch(top, "path", [ell(TABLE.rx - 12, TABLE.ry - 12)], { fill: "muted", sw: 2 });
      const rim = Loom.svg("g", {}, table.inner);
      kit.sketch(rim, "path", [ell(TABLE.rx, TABLE.ry)], { fill: "none", sw: 5 });
    }
    m.draw(table, tRoom + 0.15, { dur: drawDur * 0.9 });
    const board = ctx.el("board", { x: 0, y: 0, w: 1920, h: 1080, kind: "scenery", exit: "recede" });
    {
      const g = Loom.svg("g", {}, board.inner);
      kit.sketch(g, "rectangle", [BOARD.x, BOARD.y, BOARD.w, BOARD.h], { fill: "surface", sw: 6 });
      kit.sketch(g, "rectangle", [BOARD.x + 14, BOARD.y + 14, BOARD.w - 28, BOARD.h - 28], { fill: "none", stroke: "muted", sw: 2 });
      kit.line(g, BOARD.x + 60, BOARD.y + BOARD.h + 14, BOARD.x + BOARD.w - 60, BOARD.y + BOARD.h + 14, { sw: 5 }); // marker tray
    }
    m.draw(board, tBoard, { dur: drawDur * 0.6 });
    function person(E, lx, ly, seatToward) {
      const dx = seatToward.x - (E.x + lx), dy = seatToward.y - (E.y + ly), L = Math.hypot(dx, dy) || 1;
      const u = { x: dx / L, y: dy / L }, v = { x: -u.y, y: u.x };
      const p0 = { x: lx - 62 * v.x - 10 * u.x, y: ly - 62 * v.y - 10 * u.y };
      const p1 = { x: lx + 62 * v.x - 10 * u.x, y: ly + 62 * v.y - 10 * u.y };
      const c = { x: lx - 80 * u.x, y: ly - 80 * u.y };
      kit.sketch(Loom.svg("g", {}, E.inner), "path", [`M${f(p0.x)} ${f(p0.y)} Q${f(c.x)} ${f(c.y)} ${f(p1.x)} ${f(p1.y)}`], { fill: "none", sw: 5 });
      const rot = Loom.svg("g", {}, E.inner);
      kit.disc(rot, lx, ly, HEAD_R, { fill: "ink" });
      kit.path(rot, `M${lx + HEAD_R - 4} ${ly} L${lx + HEAD_R + 14} ${ly}`, { stroke: "ink", sw: 7 });
      return rot;
    }
    const facing = (from, to) => Math.atan2(to.y - from.y, to.x - from.x) * 180 / Math.PI;
    const wrap180 = (a) => { while (a > 180) a -= 360; while (a <= -180) a += 360; return a; };
    const heads = PEERS.map((P, i) => {
      const E = ctx.el(P.name, { x: P.x - 80, y: P.y - 80, w: 160, h: 160, kind: "character", exit: "recede" });
      const rot = person(E, 80, 80, { x: TABLE.cx, y: TABLE.cy });
      const a0 = facing(P, NOTE_CENTRE);        // looking at the note on the board
      const a1 = a0 + wrap180(facing(P, ENG) - a0); // shortest way round onto the engineer
      rot.setAttribute("transform", `rotate(${f(a0)} 80 80)`);
      m.pop(E, tOpen + i * popGap, { overshoot: false });
      Loom.drive((e) => rot.setAttribute("transform", `rotate(${(a0 + (a1 - a0) * e).toFixed(2)} 80 80)`),
        tTurn + i * turnGap, turnDur, "editorial", { kind: "value_travel", beat: ctx.beat.id, name: P.name, content: true });
      return { P, E };
    });
    const eng = ctx.el("engineer", { x: ENG.x - 120, y: ENG.y - 90, w: 240, h: 210, kind: "character", exit: "recede" });
    {
      const rot = person(eng, 120, 90, { x: TABLE.cx, y: TABLE.cy });
      rot.setAttribute("transform", `rotate(${f(facing(ENG, { x: TABLE.cx, y: TABLE.cy }))} 120 90)`);
      kit.sketch(Loom.svg("g", {}, eng.inner), "circle", [120, 90, RING_R * 2], { fill: "none", stroke: "accent2", sw: 5 });
      kit.text(eng.inner, "engineer", { role: "label", x: 20, y: 156, w: 200, h: 48, maxLines: 1, align: "center", color: "ink" });
    }
    m.pop(eng, tOpen + PEERS.length * popGap, { overshoot: false });
    const sight = ctx.el("sight_lines", { x: 0, y: 0, w: 1920, h: 1080, kind: "connector", exit: "recede" });
    const lines = heads.map(({ P }) => {
      const dx = ENG.x - P.x, dy = ENG.y - P.y, L = Math.hypot(dx, dy), d = { x: dx / L, y: dy / L };
      const mid = { x: (P.x + ENG.x) / 2, y: (P.y + ENG.y) / 2 };
      const C = { x: mid.x - d.y * P.bend, y: mid.y + d.x * P.bend };
      const un = (a, b) => { const l = Math.hypot(b.x - a.x, b.y - a.y) || 1; return { x: (b.x - a.x) / l, y: (b.y - a.y) / l }; };
      const uS = un(P, C), uT = un(ENG, C);
      const S0 = { x: P.x + uS.x * (HEAD_R + 18), y: P.y + uS.y * (HEAD_R + 18) };
      const T0 = { x: ENG.x + uT.x * (RING_R + 10), y: ENG.y + uT.y * (RING_R + 10) };
      const N = 160, pts = [], cum = [0];
      for (let k = 0; k <= N; k++) {
        const t = k / N, a = (1 - t) * (1 - t), b = 2 * (1 - t) * t, c = t * t;
        pts.push({ x: a * S0.x + b * C.x + c * T0.x, y: a * S0.y + b * C.y + c * T0.y });
        if (k) cum.push(cum[k - 1] + Math.hypot(pts[k].x - pts[k - 1].x, pts[k].y - pts[k - 1].y));
      }
      const total = cum[N];
      const at = (s) => { // point at arc length s
        let lo = 0, hi = N;
        while (hi - lo > 1) { const mid2 = (lo + hi) >> 1; if (cum[mid2] < s) lo = mid2; else hi = mid2; }
        const span = cum[hi] - cum[lo] || 1, q = (s - cum[lo]) / span;
        return { x: pts[lo].x + (pts[hi].x - pts[lo].x) * q, y: pts[lo].y + (pts[hi].y - pts[lo].y) * q };
      };
      const DASH = 16, PERIOD = 28, segs = [];
      const g = Loom.svg("g", {}, sight.inner);
      for (let s0 = 0; s0 < total - 6; s0 += PERIOD) {
        const s1 = Math.min(s0 + DASH, total);
        let dd = "";
        for (let q = 0; q <= 3; q++) { const p = at(s0 + (s1 - s0) * q / 3); dd += (q ? "L" : "M") + f(p.x) + " " + f(p.y) + " "; }
        const seg = kit.path(g, dd, { stroke: "accent", sw: 3.4 });
        seg.setAttribute("opacity", "0");
        segs.push({ seg, s0 });
      }
      return { total, segs };
    });
    sight.revealT = tLines; sight.revealKind = "draw";
    Loom.drive((e) => {
      for (const ln of lines) {
        const reach = e * ln.total;   // every line reaches the engineer at the same moment
        for (const sg of ln.segs) sg.seg.setAttribute("opacity", Math.max(0, Math.min(1, (reach - sg.s0) / 16)).toFixed(2));
      }
    }, tLines, drawDur * 0.8, "move", { kind: "draw", beat: ctx.beat.id, name: "sight_lines", content: true });
    const cap = ctx.el("caption", { x: 680, y: 815, w: 600, h: 56, kind: "text", exit: "wipe" });
    kit.kicker(cap.inner, "Every head turns", { x: 0, y: 0, w: 600, h: 56, align: "center", color: "ink" });
    m.settle(cap, tCap, { dy: 14 });
  },
});

Loom.scene("b11", {
  build(ctx) {
    const { kit, m } = ctx;
    const S = Loom.style;
    const bid = ctx.beat.id;
    const SPINE_Y = 640;
    const SPINE_X0 = 250, SPINE_X1 = 1720;            // stroke start (right of the moon) and arrow tip
    const MARK_X = [520, 960, 1400];
    const FRAME_W = 300, FRAME_H = 200, FRAME_Y = 380;
    const tStep = ctx.cue("Step two");
    const tTwo = ctx.cue("two");
    const tRebuild = ctx.cue("rebuild the night");
    const tOrder = ctx.cue("in order");
    const tAs = ctx.cue("as each");
    const tPerson = ctx.cue("person");
    const f1 = (v) => v.toFixed(1);
    function smoothPath(pts) {                         // Catmull-Rom through pts -> cubic bezier path
      let d = `M${f1(pts[0][0])} ${f1(pts[0][1])}`;
      for (let i = 0; i < pts.length - 1; i++) {
        const p0 = pts[Math.max(0, i - 1)], p1 = pts[i], p2 = pts[i + 1], p3 = pts[Math.min(pts.length - 1, i + 2)];
        const c1 = [p1[0] + (p2[0] - p0[0]) / 6, p1[1] + (p2[1] - p0[1]) / 6];
        const c2 = [p2[0] - (p3[0] - p1[0]) / 6, p2[1] - (p3[1] - p1[1]) / 6];
        d += ` C${f1(c1[0])} ${f1(c1[1])} ${f1(c2[0])} ${f1(c2[1])} ${f1(p2[0])} ${f1(p2[1])}`;
      }
      return d;
    }
    function wobbleRect(x, y, w, h, r, rng, j) {
      const q = () => (rng() - 0.5) * 2 * j;
      return `M${f1(x + r + q())} ${f1(y + q())} L${f1(x + w - r + q())} ${f1(y + q())} Q${f1(x + w + q())} ${f1(y + q())} ${f1(x + w + q())} ${f1(y + r + q())}` +
        ` L${f1(x + w + q())} ${f1(y + h - r + q())} Q${f1(x + w + q())} ${f1(y + h + q())} ${f1(x + w - r + q())} ${f1(y + h + q())}` +
        ` L${f1(x + r + q())} ${f1(y + h + q())} Q${f1(x + q())} ${f1(y + h + q())} ${f1(x + q())} ${f1(y + h - r + q())}` +
        ` L${f1(x + q())} ${f1(y + r + q())} Q${f1(x + q())} ${f1(y + q())} ${f1(x + r + q())} ${f1(y + q())} Z`;
    }
    const hdr = ctx.el("rule_header", { x: 160, y: 96, w: 1600, h: 70, kind: "text", exit: "wipe" });
    kit.rect(hdr.inner, 0, 0, 1600, 70, { fill: "field2", stroke: "muted", r: 14 });
    kit.text(hdr.inner, "To learn and fix the system, not to blame", { role: "label", x: 0, y: 0, w: 1600, h: 70, maxLines: 1, align: "center", valign: "middle", color: "muted" });
    m.reveal(hdr, tStep, { dy: 10 });
    const tag = ctx.el("step_tag", { x: 160, y: 196, w: 420, h: 48, kind: "text", exit: "recede" });
    kit.kicker(tag.inner, "Step two", { x: 0, y: 0, w: 420, h: 48 });
    m.drop(tag, tTwo);
    const spine = ctx.el("spine", { x: 160, y: SPINE_Y - 50, w: 1600, h: 100, kind: "connector", exit: "recede" });
    const lx = (x) => x - 160, ly = SPINE_Y - (SPINE_Y - 50);   // station x -> element-local x; spine centre y -> 50
    const rngS = Loom.rng("b11:spine");
    const pts = [];
    const nSeg = 8;
    for (let i = 0; i <= nSeg; i++) {
      const x = SPINE_X0 + ((SPINE_X1 - 24 - SPINE_X0) * i) / nSeg;
      pts.push([lx(x), ly + (i === 0 || i === nSeg ? 0 : (rngS() - 0.5) * 5)]);
    }
    const line = kit.path(spine.inner, smoothPath(pts), { stroke: "ink", sw: 5 });
    const LEN = line.getTotalLength() || 1;
    line.setAttribute("stroke-dasharray", `${LEN} ${LEN * 2}`);
    line.setAttribute("stroke-dashoffset", LEN);
    const tipX = lx(SPINE_X1);
    const chev = kit.path(spine.inner, `M${f1(tipX - 30)} ${ly - 20} L${f1(tipX)} ${ly + 1} L${f1(tipX - 28)} ${ly + 22}`, { stroke: "ink", sw: 5 });
    const CLEN = chev.getTotalLength() || 1;
    chev.setAttribute("stroke-dasharray", `${CLEN} ${CLEN * 2}`);
    chev.setAttribute("stroke-dashoffset", CLEN);
    chev.setAttribute("opacity", 0);
    const moon = Loom.svg("g", {}, spine.inner);
    kit.icon(moon, "moon", { x: lx(200), y: ly, size: 76, color: "ink" });
    m.pop(moon, tRebuild);
    const easeD = Loom.bezier(0.35, 0.0, 0.5, 1);
    const tDraw0 = tRebuild + 0.14;
    const tDraw1 = tOrder + 0.5;
    const dDraw = tDraw1 - tDraw0;
    Loom.drive((e) => {
      line.setAttribute("stroke-dashoffset", (LEN * (1 - e)).toFixed(2));
      const c = Math.max(0, Math.min(1, (e - 0.94) / 0.06));
      chev.setAttribute("opacity", c > 0.001 ? 1 : 0);
      chev.setAttribute("stroke-dashoffset", (CLEN * (1 - c)).toFixed(2));
    }, tDraw0, dDraw, easeD, { kind: "draw", beat: bid, name: "spine", content: true });
    spine.revealT = tRebuild; spine.revealKind = "draw";
    const headAt = (x) => {
      const frac = Math.max(0, Math.min(1, (x - SPINE_X0) / (SPINE_X1 - 24 - SPINE_X0)));
      let lo = 0, hi = 1;
      for (let i = 0; i < 40; i++) { const mid = (lo + hi) / 2; if (easeD(mid) < frac) lo = mid; else hi = mid; }
      return tDraw0 + ((lo + hi) / 2) * dDraw;
    };
    const mk = ctx.el("markers", { x: 490, y: SPINE_Y - 40, w: 940, h: 80, kind: "node", exit: "recede" });
    MARK_X.forEach((x, i) => {
      const g = Loom.svg("g", {}, mk.inner);
      const cx = x - 490, cy = 40;
      kit.line(g, cx, cy - 24, cx, cy + 24, { stroke: "ink", sw: 4 });
      kit.disc(g, cx, cy, 17, { fill: "accent2" });
      m.pop(g, headAt(x) - 0.02, { overshoot: false, dur: 0.32 });
    });
    mk.revealT = headAt(MARK_X[0]) - 0.02; mk.revealKind = "pop";
    const FX = MARK_X.map((x) => x - FRAME_W / 2);        // 370, 810, 1250
    const frames = ctx.el("frames", { x: FX[0], y: FRAME_Y, w: FX[2] + FRAME_W - FX[0], h: 250, kind: "card", exit: "displace" });
    const defs = Loom.svg("defs", {}, frames.inner);
    FX.forEach((fx, i) => {
      const x0 = fx - FX[0];
      const g = Loom.svg("g", {}, frames.inner);
      const rngF = Loom.rng("b11:frame:" + i);
      kit.rect(g, x0, 0, FRAME_W, FRAME_H, { fill: "surface", r: 14, crisp: true });
      const outline = kit.path(g, wobbleRect(x0, 0, FRAME_W, FRAME_H, 14, rngF, 1.6), { stroke: "muted", sw: 3, dash: "14 10" });
      void outline;
      kit.line(g, x0 + FRAME_W / 2, FRAME_H + 4, x0 + FRAME_W / 2, 236, { stroke: "muted", sw: 3, dash: "6 8", crisp: true });
      kit.disc(g, x0 + 6, 6, 25, { fill: "surface" });
      kit.icon(g, "eye", { x: x0 + 6, y: 6, size: 34, color: "ink" });
      const id = Loom.uid("clip");
      const cp = Loom.svg("clipPath", { id, clipPathUnits: "userSpaceOnUse" }, defs);
      const box = { x: x0 - 30, y: -30, w: FRAME_W + 60, h: 290 };
      const r = Loom.svg("rect", { x: box.x, y: box.y, width: box.w, height: box.h }, cp);
      g.setAttribute("clip-path", `url(#${id})`);
      Loom.tween(r, { attr: { height: 0 } }, { attr: { height: box.h }, duration: S.dur("enter") * 1.5, ease: Loom.ease.move },
        tAs + i * 0.12, { kind: "unmask", beat: bid, name: "frames", content: false });
    });
    frames.revealT = tAs; frames.revealKind = "unmask";
    const cap = ctx.el("caption", { x: 160, y: 760, w: 1600, h: 60, kind: "text", exit: "sink" });
    kit.text(cap.inner, "as they saw it then", { role: "label", x: 0, y: 0, w: 1600, h: 60, maxLines: 1, align: "center", valign: "middle", color: "muted" });
    m.settle(cap, tPerson, { dy: 16 });
  },
});

