    });
    const drawDur = ctx.style.dur("draw");
    const micro = ctx.style.dur("exit") * 0.4;   // the arrowhead's quick land / lift
    const dimDur = ctx.style.dur("move");
    arrow.revealT = tErr; arrow.revealKind = "draw";
