      const dx = seatToward.x - (E.x + lx), dy = seatToward.y - (E.y + ly), L = Math.hypot(dx, dy) || 1;
      const u = { x: dx / L, y: dy / L }, v = { x: -u.y, y: u.x };
      const p0 = { x: lx - 62 * v.x - 10 * u.x, y: ly - 62 * v.y - 10 * u.y };
      const p1 = { x: lx + 62 * v.x - 10 * u.x, y: ly + 62 * v.y - 10 * u.y };
      const c = { x: lx - 80 * u.x, y: ly - 80 * u.y };
      kit.sketch(Loom.svg("g", {}, E.inner), "path", [`M${f(p0.x)} ${f(p0.y)} Q${f(c.x)} ${f(c.y)} ${f(p1.x)} ${f(p1.y)}`], { fill: "none", sw: 5 });
      const rot = Loom.svg("g", {}, E.inner);
      kit.disc(rot, lx, ly, HEAD_R, { fill: "ink" });
      kit.path(rot, `M${lx + HEAD_R - 4} ${ly} L${lx + HEAD_R + 14} ${ly}`, { stroke: "ink", sw: 7 });
      return rot;
    }
    const facing = (from, to) => Math.atan2(to.y - from.y, to.x - from.x) * 180 / Math.PI;
    const wrap180 = (a) => { while (a > 180) a -= 360; while (a <= -180) a += 360; return a; };
    const turners = [];   // {rot, cx, cy, a0, a1, name}
    const peers = ctx.el("heads", { x: 0, y: 0, w: 1920, h: 1080, kind: "character", exit: "recede" });
    PEERS.forEach((P) => {
      const rot = person(peers, P.x, P.y, { x: TABLE.cx, y: TABLE.cy });
      const a0 = facing(P, ENG);                         // b02's frozen end state: on the engineer
      const a1 = a0 + wrap180(facing(P, TARGET) - a0);   // the short way round onto the board
      rot.setAttribute("transform", `rotate(${f(a0)} ${P.x} ${P.y})`);
      turners.push({ rot, cx: P.x, cy: P.y, a0, a1, name: P.name });
    });
    m.reveal(peers, tPeers, { dy: 0 });
    const eng = ctx.el("engineer", { x: ENG.x - 120, y: ENG.y - 90, w: 240, h: 210, kind: "character", exit: "recede" });
    {
      const rot = person(eng, 120, 90, { x: TABLE.cx, y: TABLE.cy });
      const a0 = facing(ENG, { x: TABLE.cx, y: TABLE.cy });   // as b02: looking at the table
      const a1 = a0 + wrap180(facing(ENG, TARGET) - a0);
      rot.setAttribute("transform", `rotate(${f(a0)} 120 90)`);
      kit.sketch(Loom.svg("g", {}, eng.inner), "circle", [120, 90, RING_R * 2], { fill: "none", stroke: "accent2", sw: 5 });
      kit.text(eng.inner, "engineer", { role: "label", x: 20, y: 156, w: 200, h: 48, maxLines: 1, align: "center", color: "ink" });
      turners.push({ rot, cx: 120, cy: 90, a0, a1, name: "engineer" });
    }
    m.settle(eng, tEng, { dy: 18 });
    turners.forEach((T, k) => {
      Loom.drive((e) => T.rot.setAttribute("transform", `rotate(${(T.a0 + (T.a1 - T.a0) * e).toFixed(2)} ${T.cx} ${T.cy})`),
        tTurn + k * turnGap, turnDur, "editorial", { kind: "value_travel", beat: ctx.beat.id, name: T.name, content: true });
    });
    const sight = ctx.el("gaze", { x: 0, y: 0, w: 1920, h: 1080, kind: "connector", exit: "recede" });
    const fade = Loom.svg("g", {}, sight.inner);
    const lines = PEERS.filter((P) => FAN.indexOf(P.name) >= 0).map((P) => {
      const d = Math.hypot(TARGET.x - P.x, TARGET.y - P.y);
      const u = { x: (TARGET.x - P.x) / d, y: (TARGET.y - P.y) / d };
      const s0 = HEAD_R + 20, total = d - s0;
      const DASH = 16, PERIOD = 28, segs = [];
      for (let o = 0; o < total - 6; o += PERIOD) {
        const o1 = Math.min(o + DASH, total);
        const a = { x: P.x + u.x * (s0 + o), y: P.y + u.y * (s0 + o) }, b = { x: P.x + u.x * (s0 + o1), y: P.y + u.y * (s0 + o1) };
        const seg = kit.path(fade, `M${f(a.x)} ${f(a.y)} L${f(b.x)} ${f(b.y)}`, { stroke: "accent", sw: 3.4 });
        seg.setAttribute("opacity", "0");
        segs.push({ seg, s0: o });
      }
      return { total, segs };
    });
    sight.revealT = tLines; sight.revealKind = "draw";
    Loom.drive((e) => {
      for (const ln of lines) {
        const reach = e * ln.total;   // both lines reach the board at the same moment
        for (const sg of ln.segs) sg.seg.setAttribute("opacity", Math.max(0, Math.min(1, (reach - sg.s0) / 16)).toFixed(2));
      }
    }, tLines, dLines, "move", { kind: "draw", beat: ctx.beat.id, name: "gaze", content: true });
    Loom.drive((e) => fade.setAttribute("opacity", (1 - e).toFixed(2)), tFade, 0.4, "exit", { kind: "fade", beat: ctx.beat.id, name: "gaze_fade", content: true });
    const rowY = (i) => RY0 + i * (RH + RGAP);
    FIXES.forEach((F, i) => {
      const R = ctx.el("board_fix_" + F.key, { x: RX, y: rowY(i), w: RW, h: RH, kind: "card", exit: "recede" });
      kit.rect(R.inner, 0, 0, RW, RH, { fill: "surface", r: 12, crisp: true });     // solid backing
      kit.rect(R.inner, 0, 0, RW, RH, { fill: "none", r: 12, sw: 3 });               // sketched outline
      Loom.th.iconDisc(ctx, R.inner, 54, 46, 32, F.icon, "accent2", "ink");
      kit.text(R.inner, F.label, { role: "body", x: 108, y: 6, w: RW - 108 - 16, h: 80, maxLines: 1, valign: "middle", weight: 700, size: 40 });
      kit.rect(R.inner, 22, 92, 210, 42, { fill: "surface2", r: 21, sw: 2.6 });
      kit.icon(R.inner, "user-round", { x: 50, y: 113, size: 28, color: "ink" });
      kit.text(R.inner, "Owner", { role: "label", x: 76, y: 92, w: 146, h: 42, maxLines: 1, valign: "middle", weight: 700, size: 32 });
      m.unmask(R, tRows + i * S.dur("stagger") * 1.3, { dur: S.dur("enter") * 0.9 });
    });
    const cap = ctx.el("caption", { x: 350, y: 815, w: 600, h: 56, kind: "text", exit: "wipe" });
    kit.kicker(cap.inner, "Each fix, an owner", { x: 0, y: 0, w: 600, h: 56, align: "center", color: "ink" });
    m.settle(cap, tCap, { dy: 14 });
    const ticks = ctx.el("fix_ticks", { x: RX, y: RY0, w: RW, h: 3 * RH + 2 * RGAP, kind: "mark", exit: "recede" });
    FIXES.forEach((F, i) => kit.mark(ticks.inner, "yes", RW - 52, i * (RH + RGAP) + 113, 52));
    m.settle(ticks, tOwn, { dy: 8 });
  },
});

Loom.scene("b05", {
  build(ctx) {
    const { kit, m } = ctx;
    const S = Loom.style;
    const year = ctx.el("year_stamp", { x: 150, y: 250, w: 620, h: 180, kind: "value", exit: "recede" });
    kit.text(year.inner, "1885", { role: "display", x: 0, y: 0, w: 620, h: 180, maxLines: 1, color: "accent2" });
    m.stamp(year, ctx.cue("1885"));
    const name = ctx.el("name_tag", { x: 150, y: 450, w: 640, h: 130, kind: "text", exit: "wipe" });
    kit.text(name.inner, "Hermann Ebbinghaus", { role: "title", x: 0, y: 0, w: 640, h: 130, maxLines: 2, size: 64 });
    m.unmask(name, ctx.cue("Hermann Ebbinghaus") + 0.1);
    const how = ctx.el("method_tag", { x: 150, y: 620, w: 640, h: 60, kind: "text", exit: "sink" });
    kit.text(how.inner, "measured his own memory", { role: "lead", x: 0, y: 0, w: 640, h: 60, maxLines: 1, color: "muted" });
    m.settle(how, ctx.cue("measured this on himself"));
    const NX = 880, NY = 150, NW = 880, NH = 730;
    const book = ctx.el("notebook", { x: NX, y: NY, w: NW, h: NH, kind: "document", exit: "displace" });
    kit.rect(book.inner, 0, 0, NW, NH, { fill: "surface", r: 28 });
    for (let i = 0; i < 7; i++) kit.disc(book.inner, 0, 90 + i * 90, 13, { fill: "field", flat: true, shadow: false }); // binding rings
    kit.kicker(book.inner, "nonsense syllables", { x: 70, y: 44, w: 520, h: 40 });
    m.settle(book, ctx.cue("measured this on himself") + 0.2, { dy: 40 });
    const clock = ctx.el("clock", { x: NX + NW - 170, y: NY + 20, w: 120, h: 120, kind: "instrument", exit: "iris" });
    kit.disc(clock.inner, 60, 60, 54, { fill: "field", shadow: false });
    kit.disc(clock.inner, 60, 60, 44, { fill: "ink", flat: true, shadow: false });
    const hand = Loom.svg("line", { x1: 60, y1: 60, x2: 60, y2: 26, stroke: S.c("accent"), "stroke-width": 7, "stroke-linecap": "round" }, clock.inner);
    Loom.svg("circle", { cx: 60, cy: 60, r: 6, fill: S.c("field") }, clock.inner);
    m.pop(clock, ctx.cue("nonsense syllables") + 0.2, { overshoot: false });
    const syl = ["DAX", "BOK", "ZEF", "WUG", "KIP", "LOM", "FEP", "RIZ"];
    const lost = new Set([1, 3, 4, 6]);
    const cols = 4, cw = 170, ch = 150, gx = 32, gy = 40;
    const x0 = NX + (NW - (cols * cw + (cols - 1) * gx)) / 2, y0 = NY + 170;
    const tCards = ctx.cue("nonsense syllables");
    const cards = syl.map((s, i) => {
      const c = i % cols, r = Math.floor(i / cols);
      const E = ctx.el("card_" + (i + 1), { x: x0 + c * (cw + gx), y: y0 + r * (ch + gy), w: cw, h: ch, kind: "card", exit: "recede" });
      const face = Loom.svg("g", {}, E.inner);
      kit.rect(face, 0, 0, cw, ch, { fill: "accent4", r: 18 });
      const t = kit.text(face, s, { role: "title", x: 0, y: 0, w: cw, h: ch, maxLines: 1, align: "center", valign: "middle", size: 60, color: S.pickTokenOn("accent4") });
      m.pop(E, tCards + i * 0.07, { overshoot: false });
      return { E, face, t };
    });
    const tTest = ctx.cue("then tested");
    Loom.drive((e) => hand.setAttribute("transform", `rotate(${(e * 360).toFixed(2)} 60 60)`), tTest, 1.3, "editorial", { kind: "value_travel", beat: ctx.beat.id, content: true });
    const tKept = ctx.cue("what he kept");
    let k = 0;
    cards.forEach((c, i) => {
      if (lost.has(i)) {
        Loom.tween(c.face, { opacity: 1 }, { opacity: 0.16, duration: 0.5, ease: Loom.ease.exit }, tKept + 0.1 + k * 0.12, { kind: "fade_out", beat: ctx.beat.id, content: true });
        k++;
      } else {
        const mk = ctx.el("kept_" + (i + 1), { x: c.E.x + cw - 38, y: c.E.y - 22, w: 56, h: 56, kind: "mark", exit: "recede" });
        kit.mark(mk.inner, "yes", 28, 28, 52);
        m.pop(mk, ctx.cue("over time") + 0.05 * i, { overshoot: false });
      }
    });
  },
});

Loom.scene("b10", {
  build(ctx) {
    const { kit, m } = ctx;
    const S = Loom.style;
    const page = ctx.held ? null : null; // the page is kept by the storyboard (keep: ["page", ...]); we draw over it
    const fam = ctx.el("familiar_tag", { x: 590, y: 46, w: 330, h: 84, kind: "stamp", exit: "recede" });
    kit.pill(fam.inner, 0, 0, 330, 84, { fill: "pos" });
    kit.icon(fam.inner, "eye", { x: 52, y: 42, size: 40, color: S.pickTokenOn("pos") });
    kit.text(fam.inner, "Familiar", { role: "lead", x: 86, y: 0, w: 220, h: 84, maxLines: 1, valign: "middle", weight: 800, color: S.pickTokenOn("pos") });
    m.stamp(fam, ctx.cue("familiar is not the same"));
    const bub = ctx.el("recall_bubble", { x: 1080, y: 180, w: 700, h: 560, kind: "bubble", exit: "iris" });
    kit.rect(bub.inner, 0, 0, 700, 520, { fill: "ink", r: 60, shadow: false });
    kit.polygon(bub.inner, [[120, 510], [40, 600], [220, 510]], { fill: "ink" });
    kit.kicker(bub.inner, "from memory", { x: 60, y: 44, w: 580, h: 36, color: "surface" });
    m.iris(bub, ctx.cue("recall it") - 0.2);
    const slots = [0, 1, 2].map((i) => {
      const E = ctx.el("slot_" + (i + 1), { x: 1140, y: 290 + i * 130, w: 580, h: 100, kind: "row", exit: "recede" });
      kit.rect(E.inner, 0, 0, 580, 100, { fill: "surface2", r: 20, shadow: false });
      m.reveal(E, ctx.cue("recall it") + 0.25 + i * 0.08, { dy: 10 });
      return E;
    });
    const cover = ctx.el("cover", { x: 180, y: 130, w: 800, h: 820, kind: "cover", exit: "displace" });
    kit.rect(cover.inner, 0, 0, 800, 820, { fill: "surface", r: 22 });
    kit.icon(cover.inner, "book-x", { x: 400, y: 380, size: 150, color: "muted" });
    kit.text(cover.inner, "Notes closed", { role: "lead", x: 0, y: 490, w: 800, h: 60, maxLines: 1, align: "center", color: "muted", weight: 800 });
    const tClose = ctx.cue("Close the notes");
    Loom.tween(cover.inner, { x: -1100, opacity: 1 }, { x: 0, opacity: 1, duration: 0.55, ease: Loom.ease.move }, tClose, { kind: "travel", beat: ctx.beat.id, content: true });
    const tGone = ctx.cue("it is gone");
    slots.forEach((E, i) => {
      const q = ctx.el("question_" + (i + 1), { x: E.x + 240, y: E.y, w: 100, h: 100, kind: "text", exit: "recede" });
      kit.text(q.inner, "?", { role: "title", x: 0, y: 0, w: 100, h: 100, maxLines: 1, align: "center", valign: "middle", color: "neg", size: 80 });
      m.pop(q, tGone - 0.25 + i * 0.08, { overshoot: false });
    });
    const rec = ctx.el("recall_tag", { x: 1200, y: 780, w: 460, h: 84, kind: "stamp", exit: "recede" });
    kit.pill(rec.inner, 0, 0, 460, 84, { fill: "neg" });
    kit.text(rec.inner, "Recall: nothing", { role: "lead", x: 0, y: 0, w: 460, h: 84, maxLines: 1, align: "center", valign: "middle", weight: 800, color: S.pickTokenOn("neg") });
    m.stamp(rec, tGone + 0.35);
    void page;
  },
});
